//! The executable's generated module table.

#pragma once

#include "Containers/Span.h"
#include "CoreTypes.h"
#include "Reflection/Reflection.h"

/// The modules of this executable, in dependency order, generated by the build into the executable itself.
///
/// Only code linked into the executable can refer to them.
extern "C" const Marlin::ModuleTableEntry MarlinModuleTable[];
/// The number of entries in `MarlinModuleTable`.
extern "C" const Marlin::usize MarlinModuleTableCount;

namespace Marlin
{
/// Returns the executable's module table.
[[nodiscard]] inline Span<const ModuleTableEntry> GetModuleTable()
{
    return {MarlinModuleTable, MarlinModuleTableCount};
}
} // namespace Marlin
